import { bigint, index, jsonb, pgTable, primaryKey, text, timestamp } from 'drizzle-orm/pg-core';
import { account, passkey, session, user, verification } from './authSchema';

/**
 * Better Auth owns users, sessions, accounts, verification values and passkeys; its schema is
 * generated by `@better-auth/cli` into `authSchema.ts` and re-exported here so the rest of the app
 * has one place to import tables from.
 */
export { account, passkey, session, user, verification };

export const syncRows = pgTable(
  'sync_rows',
  {
    // Better Auth's ids are text, not uuid.
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    entity: text('entity').notNull(),
    id: text('id').notNull(),
    /** HLC, compared lexicographically — which is why it is text and not a timestamp. */
    updatedAt: text('updated_at').notNull(),
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
    data: jsonb('data').notNull(),
    /** From `sync_seq`; the cursor a client pulls from (§8.4). */
    seq: bigint('seq', { mode: 'number' }).notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.userId, table.entity, table.id] }),
    index('sync_rows_user_seq').on(table.userId, table.seq),
  ],
);

export const schema = {
  user,
  session,
  account,
  verification,
  passkey,
  syncRows,
};
